(function () {
	'use strict';

	const SELECTORS = {
		component: '[data-cmp-is="floating-bia"]'
	};

	/**
	 * Normaliza texto para slug (remove acentos, converte para minúsculas, substitui espaços por hífens)
	 * @param {string} text - Texto a ser normalizado
	 * @returns {string} - Texto normalizado em formato slug
	 */
	function normalizeToSlug(text) {
		if (!text) return '';
		return text
			.toString()
			.normalize('NFD')
			.replace(/[\u0300-\u036f]/g, '')
			.toLowerCase()
			.trim()
			.replace(/[^a-z0-9]+/g, '-')
			.replace(/(^-|-$)/g, '');
	}

	/**
	 * Detecta se é mobile
	 * @returns {boolean} - True se for mobile (viewport < 1024px)
	 */
	function isMobile() {
		return window.innerWidth < 1024;
	}

	/**
	 * Obtém o segmento da conta do usuário
	 * @returns {string} - Segmento da conta (classic, exclusive, prime, next) ou 'classic' como padrão
	 */
	function getUserSegment() {
		// 1. Tenta obter do dataLayer
		if (window.dataLayer && window.dataLayer.length > 0) {
			for (var i = window.dataLayer.length - 1; i >= 0; i--) {
				if (window.dataLayer[i].user && window.dataLayer[i].user.segment) {
					return window.dataLayer[i].user.segment;
				}
			}
		}

		// 2. Tenta obter do script do header-footer (parâmetro type)
		var headerFooterScript = document.querySelector('script[src*="header-footer"]');
		if (headerFooterScript) {
			var scriptSrc = headerFooterScript.getAttribute('src');
			if (scriptSrc) {
				var typeMatch = scriptSrc.match(/[?&]type=([^&]+)/);
				if (typeMatch && typeMatch[1]) {
					return typeMatch[1];
				}
			}
		}

		return 'classic';
	}

	/**
	 * Envia evento para GTM
	 * @param {object} element - Elemento do componente
	 * @param {string} eventType - Tipo de evento (click_modal_open, link_click)
	 */
	function sendGTMEvent(element, eventType) {
		const elementName = element.getAttribute('data-gtm-element-name') || 'floating-bia';
		const location = element.getAttribute('data-gtm-location') || 'unknown';
		const action = element.getAttribute('data-gtm-action') || eventType;
		const product = element.getAttribute('data-gtm-product') || '';
		const flow = element.getAttribute('data-gtm-flow') || '';
		const segment = element.getAttribute('data-gtm-segment') || getUserSegment();
		const loggedUser = element.getAttribute('data-gtm-logged-user') || '';

		if (window.dataLayer) {
			window.dataLayer.push({
				event: 'click',
				eventAction: action,
				elementName: elementName,
				elementType: 'floating-bia',
				location: location,
				product: product,
				flow: flow,
				segment: segment,
				loggedUser: loggedUser,
				timestamp: new Date().toISOString()
			});
		}
	}

	/**
	 * Abre o modal
	 * @param {object} element - Elemento do componente
	 */
	function openModal(element) {
		const modal = element.querySelector('.cmp-floating-bia__modal');
		if (modal) {
			// Mark component as open to control focus styles
			element.classList.add('is-open');
			modal.classList.add('is-active');
			modal.setAttribute('aria-hidden', 'false');
			// Do not lock page scroll for popover behavior

			// Envia evento GTM
			sendGTMEvent(element, 'click_modal_open');
		}
	}

	/**
	 * Fecha o modal
	 * @param {object} element - Elemento do componente
	 */
	function closeModal(element) {
		const modal = element.querySelector('.cmp-floating-bia__modal');
		if (modal) {
			element.classList.remove('is-open');
			modal.classList.remove('is-active');
			modal.setAttribute('aria-hidden', 'true');
			// No scroll lock applied; nothing to restore here
		}
	}

	/**
	 * Inicializa o componente
	 * @param {object} element - Elemento do componente
	 */
	function initComponent(element) {
		const modal = element.querySelector('.cmp-floating-bia__modal');
		const closeButton = element.querySelector('.cmp-floating-bia__modal-close');
		const backdrop = element.querySelector('.cmp-floating-bia__modal-backdrop');
		const linkHref = element.getAttribute('data-link-href');

		/**
		 * Handler de clique no componente
		 */
		function handleCardClick(e) {
			e.preventDefault();
			e.stopPropagation();

			if (isMobile()) {
				// Mobile: redireciona para link
				if (linkHref) {
					sendGTMEvent(element, 'click_mobile_redirect');
					window.location.href = linkHref;
				}
			} else {
				// Desktop: abre modal
				openModal(element);
			}
		}

		/**
		 * Handler de clique no botão de fechar
		 */
		function handleCloseClick(e) {
			e.preventDefault();
			e.stopPropagation();
			closeModal(element);
		}

		/**
		 * Handler de clique no backdrop
		 */
		function handleBackdropClick(e) {
			if (e.target === backdrop) {
				e.preventDefault();
				closeModal(element);
			}
		}

		/**
		 * Handler de tecla ESC
		 */
		function handleEscapeKey(e) {
			if (e.key === 'Escape' || e.keyCode === 27) {
				closeModal(element);
			}
		}

		/**
		 * Handler de resize da janela para fechar modal em mobile
		 */
		function handleWindowResize() {
			if (isMobile() && modal && modal.classList.contains('is-active')) {
				closeModal(element);
			}
		}

		/**
		 * Handler de Enter e Space para acessibilidade
		 */
		function handleKeyDown(e) {
			if (e.key === 'Enter' || e.key === ' ') {
				e.preventDefault();
				handleCardClick(e);
			}
		}

		// Event listeners
		element.addEventListener('click', handleCardClick);

		if (closeButton) {
			closeButton.addEventListener('click', handleCloseClick);
		}

		if (backdrop) {
			backdrop.addEventListener('click', handleBackdropClick);
		}

		if (modal) {
			modal.addEventListener('keydown', handleEscapeKey);
		}

		element.addEventListener('keydown', handleKeyDown);
		window.addEventListener('resize', handleWindowResize);

		// Cleanup
		element.__cleanup = function () {
			element.removeEventListener('click', handleCardClick);
			if (closeButton) {
				closeButton.removeEventListener('click', handleCloseClick);
			}
			if (backdrop) {
				backdrop.removeEventListener('click', handleBackdropClick);
			}
			if (modal) {
				modal.removeEventListener('keydown', handleEscapeKey);
			}
			element.removeEventListener('keydown', handleKeyDown);
			window.removeEventListener('resize', handleWindowResize);
		};
	}

	/**
	 * Inicializa todos os componentes no DOM
	 */
	function init() {
		const components = document.querySelectorAll(SELECTORS.component);
		components.forEach(initComponent);
	}

	/**
	 * Reinicializa componentes (para AEM author ou SPA updates)
	 */
	window.addEventListener('load', init);
	document.addEventListener('DOMContentLoaded', init);

	// Mutation Observer para detectar adição dinâmica de componentes
	if (window.MutationObserver) {
		const observer = new MutationObserver(function () {
			const components = document.querySelectorAll(SELECTORS.component);
			components.forEach(function (component) {
				if (!component.__initialized) {
					component.__initialized = true;
					initComponent(component);
				}
			});
		});

		observer.observe(document.body, {
			childList: true,
			subtree: true
		});

		window.__iconModalCardObserver = observer;
	}

	// Inicialização imediata
	init();
})();
